//! Logical generations share one physical ledger. No heap transaction registry.
use crate::{
    types::{invalid, stopped},
    *,
};

/// Same-job publication token. Copies become stale together when replaced.
#[derive(Debug, Clone, Copy)]
pub struct CacheGeneration {
    cache: JobDashCache,
    scope: u64,
}
/// Exclusive construction borrow; dropping or aborting retires only staged data.
/// No job/Vec/lease escape. Handles remain bound to their original generation.
pub struct CacheTransaction<'a> {
    job: &'a mut RasterJob,
    scope: u64,
    old: Option<CacheGeneration>,
    committed: bool,
}
impl RasterJob {
    pub(crate) fn cache_scope(&self, cache: JobDashCache, staged: bool) -> Result<u64> {
        self.require_pool(cache.segments, RasterPool::Dash)?;
        self.require_pool(cache.joins, RasterPool::Dash)?;
        self.require_pool(cache.shapes, RasterPool::Dash)?;
        let scope = self.checked(cache.segments)?.scope;
        for s in [
            self.checked(cache.segments)?,
            self.checked(cache.joins)?,
            self.checked(cache.shapes)?,
        ] {
            if s.scope != scope || (!staged && !s.published) {
                return Err(invalid(0));
            }
        }
        Ok(scope)
    }
    fn generation(&self, generation: CacheGeneration) -> Result<()> {
        if generation.scope == 0 || self.cache_scope(generation.cache, false)? != generation.scope {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Starts an explicit per-cache 16MiB/65536-cell/1M-reference generation.
    /// Physical old/new overlap, registry growth and history use the caller ledger.
    pub fn begin_cache<'a>(
        &'a mut self,
        source: &SourceOwner,
        old: Option<CacheGeneration>,
        control: &mut dyn WorkControl,
    ) -> Result<CacheTransaction<'a>> {
        self.validate_source(source)?;
        if self.cache_transaction.is_some() {
            return Err(invalid(0));
        }
        if let Some(old) = old {
            self.cache_view(old, control)?;
        }
        control.checkpoint().map_err(stopped)?;
        let scope = self.next;
        self.next = scope.checked_add(1).ok_or_else(crate::memory::arithmetic)?;
        self.cache_transaction = Some(scope);
        Ok(CacheTransaction {
            job: self,
            scope,
            old,
            committed: false,
        })
    }
    /// Descriptor compatibility for existing lower readers/composition. Each use
    /// still validates liveness, roles and generation; this transfers no ownership.
    pub fn cache_descriptor(&self, generation: CacheGeneration) -> Result<JobDashCache> {
        self.generation(generation)?;
        Ok(generation.cache)
    }
    pub fn cache_view(
        &self,
        generation: CacheGeneration,
        control: &mut dyn WorkControl,
    ) -> Result<JobDashView<'_>> {
        self.dash_view(self.cache_descriptor(generation)?, control)
    }
    pub(crate) fn release_scope(&mut self, scope: u64) -> Result<()> {
        for i in 0..self.slots.len() {
            if self.slots[i].active && self.slots[i].scope == scope {
                self.release_slot(i)?;
            }
        }
        Ok(())
    }
}
impl CacheTransaction<'_> {
    fn require<T: JobElement>(&self, h: JobBuffer<T>) -> Result<()> {
        if self.job.checked(h)?.scope != self.scope {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Uses the actual typed job arena; only original Dash/Grid roles are legal.
    pub fn buffer<T: JobElement>(
        &mut self,
        pool: RasterPool,
        cap: usize,
        control: &mut dyn WorkControl,
    ) -> Result<JobBuffer<T>> {
        if !matches!(pool, RasterPool::Dash | RasterPool::Grid) {
            return Err(invalid(0));
        }
        self.job.scoped_buffer(pool, cap, self.scope, control)
    }
    pub fn reserve<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.reserve(h, capacity, control)
    }
    pub fn extend<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        values: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.extend(h, values, control)
    }
    pub fn slice<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&[T]> {
        self.require(h)?;
        self.job.slice(h)
    }
    pub fn slice_mut<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<&mut [T]> {
        self.require(h)?;
        self.job.slice_mut(h)
    }
    pub fn capacity<T: JobElement>(&self, h: JobBuffer<T>) -> Result<usize> {
        self.require(h)?;
        self.job.capacity(h)
    }
    pub fn truncate<T: JobElement>(&mut self, h: JobBuffer<T>, len: usize) -> Result<()> {
        self.require(h)?;
        self.job.truncate(h, len)
    }
    pub fn shrink_to<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.shrink_to(h, capacity, control)
    }
    pub fn clear_capacity<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.clear_capacity(h, control)
    }
    pub fn release<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<()> {
        self.require(h)?;
        self.job.release(h)
    }
    pub fn stats(&self) -> RenderMemoryStats {
        self.job.stats()
    }
    /// Validate actual payload and same-scope grids before retiring any old slot.
    /// Consuming self makes duplicate commit impossible; copied descriptors confer
    /// no publication authority. Validation failure invokes unconditional cleanup.
    /// ```compile_fail,E0382
    /// use vexel_scene::*;
    /// fn replay(tx: CacheTransaction<'_>, cache: JobDashCache, c: &mut dyn WorkControl) {
    ///     let _ = tx.commit(cache, c);
    ///     let _ = tx.commit(cache, c); // publication authority was consumed
    /// }
    /// ```
    pub fn commit(
        mut self,
        cache: JobDashCache,
        control: &mut dyn WorkControl,
    ) -> Result<CacheGeneration> {
        if self.job.cache_scope(cache, true)? != self.scope {
            return Err(invalid(0));
        }
        self.job.dash_view_staged(cache, control)?;
        if let Some(old) = self.old {
            self.job.generation(old)?;
        }
        control.checkpoint().map_err(stopped)?;
        // No allocation/cancellation/fallible validation after this boundary.
        if let Some(old) = self.old {
            self.job.release_scope(old.scope)?;
        }
        for s in &mut self.job.slots {
            if s.active && s.scope == self.scope {
                s.published = true;
            }
        }
        self.job.cache_transaction = None;
        self.committed = true;
        Ok(CacheGeneration {
            cache,
            scope: self.scope,
        })
    }
    pub fn abort(self) {
        drop(self);
    }
}
impl Drop for CacheTransaction<'_> {
    fn drop(&mut self) {
        if !self.committed {
            // Private leases cannot be corrupted by callers. If cleanup ever
            // fails, unpublished slots remain and finish refuses success.
            if self.job.release_scope(self.scope).is_ok() {
                self.job.cache_transaction = None;
            }
        }
    }
}
//! Owning job allocations. Handles never own or expose a Vec or a lease.
use crate::memory::{arithmetic, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
use std::marker::PhantomData;

/// Copy-only, allocation-free scalar records supported by the job arena.
/// Sealed: nested heap payloads cannot bypass accounting through an element.
pub trait JobElement: Copy + private::Element {}
#[derive(Debug, PartialEq, Eq)]
pub struct JobBuffer<T> {
    owner: u64,
    slot: usize,
    serial: u64,
    marker: PhantomData<T>,
}
impl<T> JobBuffer<T> {
    pub(crate) fn identity(self) -> (u64, usize, u64) {
        (self.owner, self.slot, self.serial)
    }
}
impl<T> Copy for JobBuffer<T> {}
impl<T> Clone for JobBuffer<T> {
    fn clone(&self) -> Self {
        *self
    }
}

/// Reference caps apply to retained actual capacity, including nested grid data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RasterPool {
    Scratch,
    Dash,
    Grid,
    Boundary,
    Output,
    GroupScratch,
}
impl RasterPool {
    fn cap(self) -> usize {
        match self {
            Self::Scratch => usize::MAX,
            Self::GroupScratch => 64 * 1024 * 1024,
            Self::Dash => 16 * 1024 * 1024,
            Self::Grid => 16 * 1024 * 1024,
            Self::Boundary => usize::MAX, // original cap is marking WORK, not bits
            Self::Output => usize::MAX,
        }
    }
    fn error(self) -> Diagnostic {
        limit(match self {
            Self::Scratch | Self::GroupScratch => LimitKind::Scratch,
            Self::Dash => LimitKind::DashCache,
            Self::Grid => LimitKind::Grid,
            Self::Boundary => LimitKind::Scratch,
            Self::Output => LimitKind::ReservedBytes,
        })
    }
}
pub(crate) struct Slot {
    pub(crate) serial: u64,
    pub(crate) data: private::Storage,
    lease: AllocationLease,
    pub(crate) pool: RasterPool,
    cap: usize,
    pub(crate) active: bool,
    next_free: Option<usize>,
    pub(crate) scope: u64,
    pub(crate) published: bool,
    boundary_work: usize,
}
/// The sole owner of every buffer. Moving/copying a handle never transfers data.
/// Drop destroys all data and the ledger; no caller release or Drop allocation.
pub struct RasterJob {
    ledger: ChargeLedger,
    pub(crate) slots: Vec<Slot>,
    metadata: Option<AllocationLease>,
    free: Option<usize>,
    pub(crate) next: u64,
    pools: [usize; 6],
    legacy_cache: [usize; 3],
    pub(crate) cache_transaction: Option<u64>,
}
/// A failed ownership transfer returns the unchanged ledger to its caller.
#[derive(Debug)]
pub struct JobStartError {
    pub diagnostic: Diagnostic,
    ledger: ChargeLedger,
}
impl JobStartError {
    pub fn into_ledger(self) -> ChargeLedger {
        self.ledger
    }
}
impl RasterJob {
    pub(crate) fn composition_parts(
        &mut self,
    ) -> (&SourceOwner, u64, &mut RenderWorkStats, &mut [Slot]) {
        let (source, owner, work) = self.ledger.composition_parts();
        (source, owner, work, &mut self.slots)
    }
    pub fn owner_identity(&self) -> LedgerIdentity {
        self.ledger.owner_identity()
    }
    pub(crate) fn publish_pattern_output(
        &mut self,
        output: JobRenderOutput,
        builder: &mut SceneBuilder,
        scene: SceneId,
        descriptor: PatternDescriptor,
        control: &mut dyn WorkControl,
    ) -> Result<PatternId> {
        output.validate(self)?;
        self.validate_source(builder.source_owner())?;
        let old = self.checked(output.pixels)?.data.bytes()?;
        if old > 16 * 1024 * 1024 {
            return Err(limit(LimitKind::Patterns));
        }
        control.checkpoint().map_err(stopped)?;
        let storage = std::mem::replace(
            &mut self.slots[output.pixels.slot].data,
            private::Storage::Byte(Vec::new()),
        );
        let private::Storage::Byte(values) = storage else {
            return Err(invalid(0));
        };
        let result = (|| {
            let tile = vexel_raster::Tile::from_owned_rgba(output.width, output.height, values)
                .map_err(|_| invalid(0))?;
            builder.append_pattern(
                scene,
                Pattern {
                    tile,
                    definition: descriptor.definition,
                    tile_width: descriptor.tile_width,
                    tile_height: descriptor.tile_height,
                    content_transform: descriptor.content_transform,
                },
                control,
            )
        })();
        // Storage is now either builder-owned and charged there, or dropped.
        // Keep its job charge until the ownership handoff finishes.
        self.pools[RasterPool::Output as usize] -= old;
        self.release_slot(output.pixels.slot)?;
        result
    }
    /// Move the SAME source/job ledger used by the coordinator into its owner.
    /// Rejects existing external leases: every live resource must be job-owned.
    pub fn new(ledger: ChargeLedger) -> std::result::Result<Self, JobStartError> {
        if let Err(diagnostic) = ledger.require_no_leases() {
            return Err(JobStartError { diagnostic, ledger });
        }
        Ok(Self {
            ledger,
            slots: Vec::new(),
            metadata: None,
            free: None,
            next: 1,
            pools: [0; 6],
            legacy_cache: [0; 3],
            cache_transaction: None,
        })
    }
    pub(crate) fn resource_mark(&self) -> u64 {
        self.next
    }
    pub(crate) fn rollback_resources(&mut self, mark: u64) -> Result<()> {
        for slot in 0..self.slots.len() {
            if self.slots[slot].active && self.slots[slot].serial >= mark {
                self.release_slot(slot)?;
            }
        }
        Ok(())
    }
    fn update_legacy_cache(&mut self, slot: usize, new_bytes: usize) -> Result<()> {
        let s = &self.slots[slot];
        if s.scope == 0 && matches!(s.pool, RasterPool::Dash | RasterPool::Grid) {
            let old = s.data.bytes()?;
            self.legacy_cache[0] = self.legacy_cache[0] - old + new_bytes;
            if s.pool == RasterPool::Grid {
                if let Some((kind, _)) = s.data.grid_kind() {
                    self.legacy_cache[kind + 1] = self.legacy_cache[kind + 1]
                        - old / s.data.element_size()
                        + new_bytes / s.data.element_size();
                }
            }
        }
        Ok(())
    }
    pub(crate) fn release_slot(&mut self, slot: usize) -> Result<()> {
        self.update_legacy_cache(slot, 0)?;
        let s = &mut self.slots[slot];
        let old = s.data.bytes()?;
        s.data = private::Storage::Byte(Vec::new());
        self.ledger.release(s.lease)?;
        self.pools[s.pool as usize] -= old;
        s.active = false;
        s.next_free = self.free;
        self.free = Some(slot);
        Ok(())
    }
    /// Reclaim even resources whose descriptor handles the caller discarded.
    /// Invalidates all tokens, retaining metadata capacity/history for reuse.
    pub fn release_all(&mut self) -> Result<()> {
        self.rollback_resources(0)?;
        self.cache_transaction = None;
        Ok(())
    }
    /// Destroy every owned payload and both metadata registries. Returned live
    /// bytes are zero: this job's source charge also ends at this boundary.
    pub fn finish(mut self) -> Result<RenderMemoryStats> {
        if self.cache_transaction.is_some() || self.slots.iter().any(|s| s.active && !s.published) {
            return Err(invalid(0));
        }
        self.rollback_resources(0)?;
        self.slots = Vec::new();
        if let Some(lease) = self.metadata.take() {
            self.ledger.release(lease)?;
        }
        Ok(self.ledger.finish_owned())
    }
    pub fn source_owner(&self) -> &SourceOwner {
        self.ledger.source_owner()
    }
    pub fn validate_source(&self, source: &SourceOwner) -> Result<()> {
        if std::sync::Arc::ptr_eq(source, self.source_owner()) {
            Ok(())
        } else {
            Err(invalid(0))
        }
    }
    pub fn stats(&self) -> RenderMemoryStats {
        self.ledger.stats()
    }
    pub fn work(&self) -> RenderWorkStats {
        self.ledger.work
    }
    pub fn charge_work(&mut self, kind: WorkKind, units: u64) -> Result<()> {
        self.ledger.work.charge(kind, units)
    }
    fn check_pool(
        &self,
        pool: RasterPool,
        scope: u64,
        old: usize,
        new: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        if matches!(pool, RasterPool::Dash | RasterPool::Grid) {
            let mut total = self.legacy_cache[0];
            if scope != 0 {
                total = 0;
                for s in &self.slots {
                    control.checkpoint().map_err(stopped)?;
                    if s.active
                        && s.scope == scope
                        && matches!(s.pool, RasterPool::Dash | RasterPool::Grid)
                    {
                        total = total.checked_add(s.data.bytes()?).ok_or_else(arithmetic)?;
                    }
                }
            }
            let total = total
                .checked_sub(old)
                .and_then(|n| n.checked_add(new))
                .ok_or_else(arithmetic)?;
            if total > 16 * 1024 * 1024 {
                return Err(limit(LimitKind::DashCache));
            }
        }
        Ok(())
    }
    fn check_grid(
        &self,
        scope: u64,
        grid: Option<(usize, usize)>,
        old: usize,
        new: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        if let Some((kind, max)) = grid {
            let mut total = self.legacy_cache[kind + 1];
            if scope != 0 {
                total = 0;
                for s in &self.slots {
                    control.checkpoint().map_err(stopped)?;
                    if s.active
                        && s.scope == scope
                        && s.pool == RasterPool::Grid
                        && s.data.grid_kind().map(|v| v.0) == Some(kind)
                    {
                        total = total
                            .checked_add(s.data.bytes()? / s.data.element_size())
                            .ok_or_else(arithmetic)?;
                    }
                }
            }
            let total = total
                .checked_sub(old)
                .and_then(|n| n.checked_add(new))
                .ok_or_else(arithmetic)?;
            if total > max {
                return Err(limit(LimitKind::Grid));
            }
        }
        Ok(())
    }
    pub(crate) fn checked<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&Slot> {
        if h.owner != self.ledger.identity() {
            return Err(invalid(0));
        }
        let s = self.slots.get(h.slot).ok_or_else(|| invalid(0))?;
        if !s.active || s.serial != h.serial || T::get(&s.data).is_none() {
            return Err(invalid(0));
        }
        Ok(s)
    }
    pub fn slice<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&[T]> {
        Ok(T::get(&self.checked(h)?.data).ok_or_else(|| invalid(0))?)

        Ok(T::get(&self.checked(h)?.data).ok_or_else(|| invalid(0))?)
    }
    /// Mutable elements only; capacity, ownership and logical length stay private.
    pub fn slice_mut<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<&mut [T]> {
        self.checked(h)?;
        Ok(T::get_mut(&mut self.slots[h.slot].data).ok_or_else(|| invalid(0))?)
    }
    pub fn capacity<T: JobElement>(&self, h: JobBuffer<T>) -> Result<usize> {
        Ok(T::get(&self.checked(h)?.data)
            .ok_or_else(|| invalid(0))?
            .capacity())
    }
    fn metadata(&mut self, control: &mut dyn WorkControl) -> Result<()> {
        if self.free.is_some() || self.slots.len() < self.slots.capacity() {
            return Ok(());
        }
        let target = self.slots.len().checked_add(1).ok_or_else(arithmetic)?;
        let grown = self
            .slots
            .capacity()
            .checked_mul(2)
            .unwrap_or(target)
            .max(target)
            .max(8);
        let result = self
            .ledger
            .allocate::<Slot>(AllocationTag::None, grown, control);
        let (mut replacement, lease) = match result {
            Err(e) if e.kind == ErrorKind::Limit(LimitKind::ReservedBytes) && grown != target => {
                self.ledger
                    .allocate::<Slot>(AllocationTag::None, target, control)?
            }
            other => other?,
        };
        // All fallible work precedes the indivisible move. No cloned source/payloads.
        replacement.append(&mut self.slots);
        self.slots = replacement;
        if let Some(old) = self.metadata.replace(lease) {
            self.ledger.release(old)?;
        }
        Ok(())
    }
    /// Create a buffer with an explicit engine element cap (no smaller default).
    pub fn buffer<T: JobElement>(
        &mut self,
        pool: RasterPool,
        cap: usize,
        control: &mut dyn WorkControl,
    ) -> Result<JobBuffer<T>> {
        self.scoped_buffer(pool, cap, 0, control)
    }
    pub(crate) fn scoped_buffer<T: JobElement>(
        &mut self,
        pool: RasterPool,
        cap: usize,
        scope: u64,
        control: &mut dyn WorkControl,
    ) -> Result<JobBuffer<T>> {
        control.checkpoint().map_err(stopped)?;
        let data = T::wrap(Vec::new());
        if !data.accepts(pool) {
            return Err(invalid(0));
        }
        let cap = if pool == RasterPool::Grid {
            cap.min(data.grid_kind().ok_or_else(|| invalid(0))?.1)
        } else {
            cap
        };
        let serial = self.next;
        let next = serial.checked_add(1).ok_or_else(arithmetic)?;
        let cap = if pool == RasterPool::Output {
            cap.min(vexel_raster::MAX_ALLOCATED_BYTES / std::mem::size_of::<T>())
        } else {
            cap
        };
        self.metadata(control)?;
        let lease = self.ledger.admit(AllocationTag::None, 0)?;
        if let Err(e) = control.checkpoint().map_err(stopped) {
            self.ledger.release(lease)?;
            return Err(e);
        }
        let slot = self.free.unwrap_or(self.slots.len());
        let entry = Slot {
            serial,
            data,
            lease,
            pool,
            cap,
            active: true,
            next_free: None,
            boundary_work: 0,
            scope,
            published: scope == 0,
        };
        if slot == self.slots.len() {
            self.slots.push(entry);
        } else {
            self.free = self.slots[slot].next_free;
            self.slots[slot] = entry;
        }
        self.next = next;
        Ok(JobBuffer {
            owner: self.ledger.identity(),
            slot,
            serial,
            marker: PhantomData,
        })
    }
    /// Replacement reserves old+new overlap BEFORE allocating. All copy loops
    /// poll control; publication follows the final checkpoint. Failure preserves
    /// old contents, capacity, token AND lease (physical history is retained).
    pub fn reserve<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.write(h, capacity, &[], false, control)
    }
    pub fn extend<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        values: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let target = self
            .slice(h)?
            .len()
            .checked_add(values.len())
            .ok_or_else(arithmetic)?;
        self.write(h, target, values, false, control)
    }
    /// Physical shrink uses a fallible replacement and accounts old/new overlap.
    /// The caller chooses the retained capacity; values are never truncated.
    pub fn shrink_to<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let old = self.capacity(h)?;
        if capacity < self.slice(h)?.len() {
            return Err(invalid(0));
        }
        if capacity >= old {
            return control.checkpoint().map_err(stopped);
        }
        if capacity == 0 {
            return self.clear_capacity(h, control);
        }
        self.write(h, capacity, &[], true, control)
    }
    fn write<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        values: &[T],
        shrink: bool,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let s = self.checked(h)?;
        control.checkpoint().map_err(stopped)?;
        let old = T::get(&s.data).ok_or_else(|| invalid(0))?;
        if capacity > s.cap {
            return Err(s.pool.error());
        }
        if capacity <= old.capacity() && !shrink {
            let dst = T::get_mut(&mut self.slots[h.slot].data).ok_or_else(|| invalid(0))?;
            let len = dst.len();
            let result = Self::copy(dst, values, control)
                .and_then(|_| control.checkpoint().map_err(stopped));
            if result.is_err() {
                dst.truncate(len);
            }
            return result;
        }
        let grid = if s.pool == RasterPool::Grid {
            s.data.grid_kind()
        } else {
            None
        };
        let scope = s.scope;
        let old_elements = old.capacity();
        self.check_grid(scope, grid, old_elements, capacity, control)?;
        let old_bytes = bytes(old)?;
        let request = capacity
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(arithmetic)?;
        let pool = s.pool;
        let cap = s.cap;
        self.check_pool(pool, scope, old_bytes, request, control)?;
        let retained = self.pools[pool as usize]
            .checked_sub(old_bytes)
            .and_then(|n| n.checked_add(request))
            .ok_or_else(arithmetic)?;
        if !matches!(pool, RasterPool::Dash | RasterPool::Grid) && retained > pool.cap() {
            return Err(pool.error());
        }
        let tag = if pool == RasterPool::Output {
            AllocationTag::Output
        } else {
            AllocationTag::ReferenceIndex
        };
        let (mut replacement, lease) = self.ledger.allocate::<T>(tag, capacity, control)?;
        let actual = bytes(&replacement)?;
        let result = (|| {
            if replacement.capacity() > cap {
                return Err(pool.error());
            }
            self.check_grid(scope, grid, old_elements, replacement.capacity(), control)?;
            self.check_pool(pool, scope, old_bytes, actual, control)?;
            let retained = (self.pools[pool as usize] - old_bytes)
                .checked_add(actual)
                .ok_or_else(arithmetic)?;
            if !matches!(pool, RasterPool::Dash | RasterPool::Grid) && retained > pool.cap() {
                return Err(pool.error());
            }
            let old = T::get(&self.slots[h.slot].data).ok_or_else(|| invalid(0))?;
            Self::copy(&mut replacement, old, control)?;
            Self::copy(&mut replacement, values, control)?;
            control.checkpoint().map_err(stopped)?;
            Ok(retained)
        })();
        let retained = match result {
            Ok(n) => n,
            Err(e) => {
                drop(replacement);
                self.ledger.release(lease)?;
                return Err(e);
            }
        };
        self.update_legacy_cache(h.slot, actual)?;
        let s = &mut self.slots[h.slot];
        s.data = T::wrap(replacement);
        self.ledger
            .release(std::mem::replace(&mut s.lease, lease))?;
        self.pools[pool as usize] = retained;
        Ok(())
    }
    fn copy<T: JobElement>(
        dst: &mut Vec<T>,
        values: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        for value in values {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            dst.push(*value);
        }
        Ok(())
    }
